import React, { useState, useEffect } from "react";
import "./Test.css";

const Test = ({ topics }) => {
  const [selectedTopic, setSelectedTopic] = useState(""); // Selected topic
  const [questions, setQuestions] = useState([]); // AI-generated questions
  const [selectedAnswers, setSelectedAnswers] = useState({}); // User-selected answers
  const [score, setScore] = useState(null); // Quiz score
  const [loading, setLoading] = useState(false); // Loading state

  // 🔹 Handle Topic Selection
  const handleTopicSelect = (topic) => {
    setSelectedTopic(topic);
    fetchAIQuestions(topic);
    setScore(null); // Reset score when changing topics
  };

  // 🔹 Fetch AI-generated MCQs based on the selected topic
  const fetchAIQuestions = async (topic) => {
    setLoading(true);
    setQuestions([]); // Reset previous questions

    try {
      const response = await fetch("http://localhost:5000/generate-questions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ topic }),
      });

      const data = await response.json();
      setQuestions(data.questions || []);
    } catch (error) {
      console.error("Error fetching AI questions:", error);
    } finally {
      setLoading(false);
    }
  };

  // 🔹 Handle Answer Selection
  const handleAnswerSelect = (qIndex, option) => {
    setSelectedAnswers((prev) => ({ ...prev, [qIndex]: option }));
  };

  // 🔹 Calculate Score
  const handleSubmit = () => {
    let correctCount = 0;
    questions.forEach((q, index) => {
      if (selectedAnswers[index] === q.correct) {
        correctCount++;
      }
    });
    setScore(correctCount);
  };

  return (
    <div className="test-container">
      <h2>Test Your Knowledge</h2>

      {/* 🔹 Display Previous Topics from LocalStorage */}  
      <div className="previous-topics">
        <h3>Previous Topics:</h3>
        {topics.length > 0 ? (
          topics.map((topic, index) => (
            <button
              key={index}
              className={`topic-btn ${selectedTopic === topic ? "selected" : ""}`}
              onClick={() => handleTopicSelect(topic)}
            >
              {topic}
            </button>
          ))
        ) : (
          <p>No topics available. Start a chat to generate topics.</p>
        )}
      </div>

      {loading && <p>Loading questions...</p>}

      {/* 🔹 Display Questions when a Topic is Selected */}
      {selectedTopic && questions.length > 0 && (
        <div className="questions-section">
          <h3>Questions for: {selectedTopic}</h3>
          {questions.map((q, index) => (
            <div key={index} className="question">
              <p>{q.question}</p>
              {q.options.map((option, idx) => (
                <button
                  key={idx}
                  className={`option-btn ${
                    selectedAnswers[index] === option ? "selected" : ""
                  }`}
                  onClick={() => handleAnswerSelect(index, option)}
                >
                  {option}
                </button>
              ))}
            </div>
          ))}
          <button onClick={handleSubmit} className="submit-btn">
            Submit
          </button>
        </div>
      )}

      {/* 🔹 Display Score after Submission */}
      {score !== null && (
        <div className="score-section">
          <h3>Your Score: {score} / {questions.length}</h3>
        </div>
      )}
    </div>
  );
};

export default Test;
